         line-height: 1.6;
       }

       form {
         display: grid;
         gap: 24px;
       }

       .form-field {
         display: grid;
         gap: 10px;
       }

       .checkbox-row {
         display: flex;
         align-items: flex-start;
         gap: 12px;
         padding: 16px;
         border: 1px solid rgba(148, 163, 184, 0.24);
         border-radius: 16px;
         background: rgba(248, 250, 252, 0.9);
       }

       input[type="checkbox"] {
         width: 18px;
         height: 18px;
         margin-top: 2px;
         accent-color: var(--primary);
       }

       label {
         font-weight: 600;
         line-height: 1.5;
       }

       .helper-text {
         margin: 0;
         color: var(--muted);
         font-size: 0.95rem;
         line-height: 1.5;
       }

       button {
         border: 0;
         border-radius: 14px;
         padding: 14px 18px;
         font: inherit;
         font-weight: 700;
         color: #fff;
         background: linear-gradient(135deg, var(--primary), var(--primary-dark));
         cursor: pointer;
         transition:
           transform 160ms ease,
           box-shadow 160ms ease,
           filter 160ms ease;
         box-shadow: 0 14px 32px rgba(37, 99, 235, 0.3);
       }

       button:hover {
         transform: translateY(-1px);
         filter: brightness(1.03);
       }

       button:focus-visible,
       input[type="checkbox"]:focus-visible {
         outline: 3px solid rgba(37, 99, 235, 0.28);
         outline-offset: 3px;
       }
     </style>
   </head>
   <body>
     <div id="app"></div>
     <script>
       const ConsentField = () => `
         <div class="form-field">
           <div class="checkbox-row">
             <input
               id="terms"
               name="terms"
               type="checkbox"
               required
               aria-describedby="terms-helper"
             />
             <label for="terms">I agree to the terms of use.</label>
           </div>
           <p id="terms-helper" class="helper-text">
             Required to continue with your submission.
           </p>
         </div>
       `;

       const SubmitButton = () => `
         <button type="submit">Submit</button>
       `;

       const App = () => `
         <main class="card">
           <span class="eyebrow">Account setup</span>
           <h1>Confirm your consent</h1>
           <p class="lead">
             Review the agreement below and submit when you are ready to proceed.
           </p>
           <form>
             ${ConsentField()}
             ${SubmitButton()}
           </form>
         </main>
       `;

       document.getElementById("app").innerHTML = App();
     </script>
   </body>
 </html>

')
